<script>function bacaGambar(input){if(input.files&&input.files[0]){var r=new FileReader();r.onload=function(e){document.getElementById('previewFoto').src=e.target.result;};r.readAsDataURL(input.files[0]);input.nextElementSibling.innerHTML=input.files[0].name;}}document.addEventListener("DOMContentLoaded",function(){const r=document.querySelectorAll('.dash .reveal');const o=new IntersectionObserver(e=>{e.forEach(x=>{if(x.isIntersecting){x.target.classList.add('active')}})},{threshold:0.12});r.forEach(x=>o.observe(x));});</script>
